const gpu = new GPU({ mode });

const table = gpu.createKernel(function () {
  return (this.thread.x + 1) * (this.thread.y + 1);
}, {
  output: [16, 16],
});

const result = table();
console.log('rows:', result.length);
console.log('row 0:', result[0]);
