`,solutionCode:`// Map: output[i] depends ONLY on input[i]. One thread per reading.
const gpu = new GPU({ mode });

const toFahrenheit = gpu.createKernel(function (celsius) {
  return celsius[this.thread.x] * 9 / 5 + 32;
}, { output: [64] });

